// ============================================================
// tools/precompile-butterchurn.cjs
// Precompile butterchurn preset equation strings into REAL functions.
//
// WHY: butterchurn's loadPreset() compiles every preset's per-frame/per-vertex
// math with `new Function("a", eqs_str + " return a;")` — which needs CSP
// 'unsafe-eval'. Sandboxed preview iframes forbid unsafe-eval, so Milkdrop
// renders black. butterchurn wraps that in `if (typeof preset.init_eqs !==
// 'function')`, so if the eqs are ALREADY functions it skips the eval entirely.
//
// This script reads vendor/butterchurn/butterchurnPresetsMinimal.min.js in
// Node (eval is fine here), turns each *_eqs_str into a real function literal,
// and emits vendor/butterchurn/butterchurnPresetsPrecompiled.js — a same-origin
// script that attaches those functions to the presets at runtime. No unsafe-eval
// is then needed in the browser -> Milkdrop works under strict CSP.
//
// Run:  node tools/precompile-butterchurn.cjs
// Re-run whenever the vendored preset set changes.
// ============================================================
'use strict';
const fs = require('fs');
const path = require('path');

// CLI:  node tools/precompile-butterchurn.cjs <packFile> <globalName> <outFile>
// Defaults to the original minimal pack for backward compatibility.
const ROOT = path.resolve(__dirname, '..');
const args = process.argv.slice(2);
const SRC = args[0] ? path.resolve(args[0]) : path.join(ROOT, 'vendor/butterchurn/butterchurnPresetsMinimal.min.js');
const GLOBAL_NAME = args[1] || 'butterchurnPresetsMinimal';
const OUT = args[2] ? path.resolve(args[2]) : path.join(ROOT, 'vendor/butterchurn/butterchurnPresetsPrecompiled.js');

const mod = require(SRC);
const api = mod.default || mod;
if (!api || typeof api.getPresets !== 'function') {
  throw new Error('Could not load presets; aborting.');
}
const presets = api.getPresets();
const names = Object.keys(presets);

// Validate a body compiles (helpers like `above` need not be defined in Node —
// new Function only parses, it does not run). Returns the safe body text.
function bodyOf(str) {
  const s = (str == null ? '' : String(str));
  try { new Function('a', s + ' return a;'); }           // syntax check only
  catch (e) { throw new Error('preset eqs parse failed: ' + e.message + ' :: ' + s.slice(0, 100)); }
  if (/<\/script/i.test(s)) throw new Error('unsafe eqs body (contains </script): ' + s.slice(0, 100));
  return s + ' return a;';
}
// Emit a real function literal: function(a){ <eqs_str> return a; }
function fn(str) { return 'function(a){' + bodyOf(str) + '}'; }

const lines = [];
lines.push('// AUTO-GENERATED by tools/precompile-butterchurn.cjs — DO NOT EDIT BY HAND.');
lines.push('// Precompiles each preset\'s equation strings (init/frame/pixel + per-shape');
lines.push('// + per-wave) into REAL functions so butterchurn\'s loadPreset() skips');
lines.push('// new Function() entirely. CSP-safe: no unsafe-eval needed at runtime.');
lines.push('// Regenerate with:  node tools/precompile-butterchurn.cjs');
lines.push('(function () {');
lines.push('  "use strict";');
lines.push('  var PC = {');

names.forEach((name, ni) => {
  const p = presets[name];
  const hasPixel = p.pixel_eqs_str != null && p.pixel_eqs_str !== '';

  const shapes = Array.isArray(p.shapes) ? p.shapes : [];
  const shapeLits = shapes.map((s) => {
    const en = s && s.baseVals && (s.baseVals.enabled !== 0);
    if (!en) return 'null';
    // enabled shape: butterchurn compiles init+frame even when empty (no-op)
    return '{init:' + fn(s.init_eqs_str) + ',frame:' + fn(s.frame_eqs_str) + '}';
  });

  const waves = Array.isArray(p.waves) ? p.waves : [];
  const waveLits = waves.map((w) => {
    const en = w && w.baseVals && (w.baseVals.enabled !== 0);
    if (!en) return 'null';
    const hasPt = w.point_eqs_str != null && w.point_eqs_str !== '';
    return '{init:' + fn(w.init_eqs_str) + ',frame:' + fn(w.frame_eqs_str) +
      ',point:' + (hasPt ? fn(w.point_eqs_str) : 'null') + '}';
  });

  lines.push('    ' + JSON.stringify(name) + ': {');
  lines.push('      init: ' + fn(p.init_eqs_str) + ',');
  lines.push('      frame: ' + fn(p.frame_eqs_str) + ',');
  lines.push('      pixel: ' + (hasPixel ? fn(p.pixel_eqs_str) : 'null') + ',');
  lines.push('      shapes: [' + shapeLits.join(',') + '],');
  lines.push('      waves: [' + waveLits.join(',') + ']');
  lines.push('    }' + (ni < names.length - 1 ? ',' : ''));
});
lines.push('  };');
lines.push(`
  // Attach the precompiled eqs to the minimal-preset objects so butterchurn's
  // loadPreset() sees real functions and skips new Function().
  function _attach() {
    var ns = (typeof window !== 'undefined') && (window[' + JSON.stringify(GLOBAL_NAME) + '] || window.butterchurnPresetsMinimal || window.butterchurnPresets);
    if (!ns) return false;
    var pre = ns.default || ns;
    if (!pre || typeof pre.getPresets !== 'function') return false;
    var P = pre.getPresets();
    Object.keys(PC).forEach(function (name) {
      var p = P[name]; if (!p) return;
      var e = PC[name];
      if (typeof e.init === 'function') p.init_eqs = e.init;
      if (typeof e.frame === 'function') p.frame_eqs = e.frame;
      p.pixel_eqs = (typeof e.pixel === 'function') ? e.pixel : '';
      if (Array.isArray(e.shapes) && Array.isArray(p.shapes)) {
        for (var i = 0; i < e.shapes.length; i++) {
          var se = e.shapes[i], ps = p.shapes[i];
          if (se && ps) { ps.init_eqs = se.init; ps.frame_eqs = se.frame; }
        }
      }
      if (Array.isArray(e.waves) && Array.isArray(p.waves)) {
        for (var j = 0; j < e.waves.length; j++) {
          var we = e.waves[j], pw = p.waves[j];
          if (we && pw) {
            pw.init_eqs = we.init; pw.frame_eqs = we.frame;
            pw.point_eqs = (typeof we.point === 'function') ? we.point : '';
          }
        }
      }
    });
    try { window.__butterchurnPrecompiled = true; } catch (e2) {}
    return true;
  }
  if (!_attach()) {
    var _iv = setInterval(function () { if (_attach()) { clearInterval(_iv); } }, 20);
    setTimeout(function () { clearInterval(_iv); }, 8000);
  }
})();`);

fs.writeFileSync(OUT, lines.join('\n'));
console.log('✓ Wrote ' + path.relative(ROOT, OUT));
console.log('  presets: ' + names.length);
console.log('  size: ' + Math.round(fs.statSync(OUT).size / 1024) + ' KB');
